#!/usr/bin/env bash
# install-hooks — copy the tracked hook source into .git/hooks/
#
# Git does not track .git/hooks/, so the actual executable lives there while
# the source-of-truth lives in scripts/. Run this after cloning or pulling:
#
#     bash scripts/install-hooks.sh
#
# Idempotent: safe to re-run after `git pull`.

set -euo pipefail

repo_root="$(git rev-parse --show-toplevel)"
hooks_dir="$repo_root/.git/hooks"

mkdir -p "$hooks_dir"

# pre-commit
cat > "$hooks_dir/pre-commit" <<'HOOK'
#!/usr/bin/env bash
# Auto-generated by scripts/install-hooks.sh — do not edit by hand.
# Source of truth: scripts/pre-commit.mjs
exec node "$(git rev-parse --show-toplevel)/scripts/pre-commit.mjs"
HOOK
chmod +x "$hooks_dir/pre-commit"

echo "Installed: $hooks_dir/pre-commit"
echo "Run 'bash scripts/install-hooks.sh' again after pulling to refresh."